-- Executed after rls.sql against the same isolated database.
set role authenticated;
set request.jwt.claim.role = 'authenticated';
set request.jwt.claim.sub = '11111111-1111-4111-8111-111111111111';
select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,false,false,false,false,false,null);
select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,false,false,true,true,true,now());
select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,false,false,true,true,true,now());
select test_assert((select attempt_count=2 and first_correct=false and first_assisted=false and latest_correct=true and latest_assisted=true and assistance_observed and completed_at is not null from learning_activity_progress),'retry deduplicated; first preserved; later help recorded');
select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,false,false,false,false,false,null);
select test_assert((select attempt_count=2 and latest_correct from learning_activity_progress),'out of order retry cannot regress summary');
select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',3,true,false,false,true,true,null);
select test_assert((select attempt_count=5 and first_correct=false and latest_correct=false and completed_at is not null from learning_activity_progress),'new-device history preserves first account outcome and prior pass time');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',3,true,false,true,true,true,null)$q$),'cannot rewrite first stream outcome');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2,false,false,false,true,true,null)$q$),'cannot replace outcome without another attempt');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-normalization',2,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,false,false,false,false,false,null)$q$),'reject incompatible version');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'unknown',1,'prediction','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,false,false,false,false,false,null)$q$),'reject unknown activity');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'application','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,false,false,false,false,false,null)$q$),'reject incompatible phase');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'prediction','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',21,false,false,false,false,false,null)$q$),'bound count');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'prediction','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,true,true,true,true,false,null)$q$),'assistance cannot be concealed');
select test_assert(test_invalid($q$select record_learning_activity(auth.uid(),'deep-orbit-cache',1,'prediction','dddddddd-dddd-4ddd-8ddd-dddddddddddd',1,false,false,true,false,false,null)$q$),'single attempt has one consistent outcome');
select test_assert(test_denied($q$insert into learning_activity_progress(user_id,activity_id,content_version,phase,source) values(auth.uid(),'forged',1,'prediction','browser_check')$q$),'direct summary write denied');
with removed as (delete from learning_activity_streams returning *) select test_assert(count(*)=0,'direct deduplication deletion denied') from removed;
select record_learning_activity(auth.uid(),'room-project-run',1,'application','cccccccc-cccc-4ccc-8ccc-cccccccccccc',1,true,false,true,false,false,now());
select test_assert((select source='learner_report' from learning_activity_progress where activity_id='room-project-run'),'external report distinguished from browser numerical check');
select test_assert((select count(*)=1 from world_progress where user_id=auth.uid()),'practice grants no lesson credit');
set request.jwt.claim.sub = '22222222-2222-4222-8222-222222222222';
select test_assert((select count(*)=0 from learning_activity_progress),'other account summaries hidden');
select test_assert((select count(*)=0 from learning_activity_streams),'other account streams hidden');
select test_assert(test_invalid($q$select record_learning_activity('11111111-1111-4111-8111-111111111111','deep-orbit-normalization',1,'prediction','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,true,false,true,false,false,null)$q$),'stale-account write rejected even if current token belongs to another account');
select record_learning_activity(auth.uid(),'deep-orbit-normalization',1,'changed_case','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,true,false,true,false,false,now());
select test_assert((select attempt_count=1 and first_correct=true from learning_activity_progress),'same stream UUID isolated by account');
reset role;
-- Account erasure cascades both the compact summary and retry records.
insert into auth.users(id,email) values('33333333-3333-4333-8333-333333333333','erase@example.test');
set role authenticated;
set request.jwt.claim.sub = '33333333-3333-4333-8333-333333333333';
select record_learning_activity(auth.uid(),'deep-orbit-cache',1,'prediction','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,true,false,true,false,false,now());
reset role;
delete from auth.users where id='33333333-3333-4333-8333-333333333333';
select test_assert((select count(*)=0 from learning_activity_progress where user_id='33333333-3333-4333-8333-333333333333'),'erasure removes summary');
select test_assert((select count(*)=0 from learning_activity_streams where user_id='33333333-3333-4333-8333-333333333333'),'erasure removes deduplication streams');
